import datetime

from airflow.providers.standard.operators.bash import BashOperator
from airflow.providers.standard.operators.empty import EmptyOperator
from airflow.sdk import DAG, Asset, Label, Param, TaskGroup, task

with DAG(
    dag_id="e2e_pipeline",
    description="End-to-end smoke test: every task must succeed",
    schedule=None,
    start_date=datetime.datetime(2026, 1, 1, tzinfo=datetime.timezone.utc),
    catchup=False,
    tags=["autoair", "e2e"],
    params={"count": Param(3, type="integer")},
) as dag:
    g_prepare = TaskGroup(group_id="prepare")
    t_start = EmptyOperator(task_id="start")
    t_hello = BashOperator(
        task_id="hello",
        task_group=g_prepare,
        bash_command='echo "run {{ run_id }} limit={{ params.count }}"',
    )

    @task(task_id="plan", task_group=g_prepare)
    def plan(count):
        return [f"echo processing part {i}" for i in range(count)]

    t_plan = plan(count=3)
    t_work = BashOperator.partial(task_id="work", outlets=[Asset(name="e2e_done")]).expand(
        bash_command=t_plan
    )

    @task(task_id="report", multiple_outputs=True)
    def report(parts):
        assert len(parts) == 3
        return {"parts": len(parts)}

    t_report = report(parts=t_plan)
    t_start >> g_prepare
    t_hello >> t_plan
    t_work >> t_report
    g_prepare >> Label("planned") >> t_work
